import { useContext, useEffect, useState } from "react";

//Context and tools
import { userContext } from "../../UserProvider";
import { findAvatarDB, findUserNameDB } from "../../firebase/ReadWriteDB";
import axiosInstance from "../../axiosInstance";
import useGoTo from "../../hooks/useGoTo";

//Components and styles
import ScreenTitle from "../base-components/ScreenTitle/ScreenTitle"; //StatisticsNewImageWindow down here \/
import PopupModal, { ConfigureGroupWindow, InviteWindow, MembersListWindow, StatisticsNewImageWindow, StatusWindowWrapper  } from "../base-components/PopupModal/PopupModal";
import TabbedContent from "../base-components/TabbedContent/TabbedContent";
import "./GroupCard.css"
import defaultGroupImage from "../../assets/images/icons/groups-icon.png";
import { ManageGroupIcon, JoinGroupIcon, DeleteIcon, GroupChatIcon, ExplorePostsIcon, LeaveGroupIcon } from "../IconSVGs";

/**
 * 
 * @param {object} props - Object to contain key-value pairs of arguments for the function.
 * @param {string} props.groupID 
 * @param {string} props.chatID 
 * @param {string} props.creationDate 
 * @param {string} props.creator
 * @param {string} props.groupName
 * @param {string} props.groupImage
 * @param {[string]} props.members
 * @param {[string]} props.admins
 * @returns 
 */
export default function GroupCard(props){

    const {user, fetchImage} = useContext(userContext);
    const {creator, groupID, chatID} = props //Don't change - no need for useState.
    const [groupName, setGroupName] = useState(props.groupName);
    const [groupImage, setGroupImage] = useState(null);
    const [members, setMembers] = useState(props.members);
    const [membersAvatars, setMembersAvatars] = useState([]);
    const [membersUsernames, setMembersUsernames] = useState([]);
    const [joinRequests, setJoinRequests] = useState(props.joinRequests);
    const [admins, setAdmins] = useState(props.admins);

    //Popups
    const [statusPopup, setStatusPopup] = useState({title:"", statusType:"", message:"", onConfirm: null, onCancel: null})
    const [isPopupOpen, setIsPopupOpen] = useState(false);
    const [isActionsPopupOpen, setIsActionsPopupOpen] = useState(false);
    const goTo = useGoTo();
    
    //DEBUG: console.log(joinRequests);
    //DEBUG: console.log(props.joinRequests);

    useEffect(() => {
        setJoinRequests(props.joinRequests);
    }, [props.joinRequests]);

    useEffect(()=>{
        const fetchGroupImage = async ()=>{

            const img = props.groupImage;

            if(typeof img === "string" && img.includes("static"))
                setGroupImage(img);
            else{
                try{
                    const fetchedAvatar = await fetchImage(img._id, false);
                    //DEBUG: console.log(`groupImage:`,img);
                    //DEBUG: console.log(`fetchedAvatar: ${fetchedAvatar}`);
                    setGroupImage(fetchedAvatar);

                }catch(err){
                    console.log("Error fetching group image, setting default." ,err);
                }
               
            }
        }

        const fetchMembersImages = async (limit=-1) =>{
            if(limit<0 && members){
                const avatars = await Promise.all(members.map(async (member)=>{
                    const avatar = await findAvatarDB(member);
                    if(avatar.includes("static"))
                        return avatar;
                    else{
                        try{
                            const fetchedAvatar = await fetchImage(avatar, false);
                            return fetchedAvatar;
                        }catch(err){
                            console.log("Error fetching member avatar" ,err);
                            return "";
                        }
                       
                    }
                }));
                setMembersAvatars(avatars);
            }
        }

        const fetchMembersUsernames = async (limit=-1) =>{ 
            if(limit<0 && members){
                const usernames = await Promise.all(members.map(async (member)=>{
                    const username = await findUserNameDB(member);
                    return {username,uid:member};
                }));
                setMembersUsernames(usernames);
            }
        }
        fetchGroupImage();
        fetchMembersImages();
        fetchMembersUsernames();
        
    },[props.groupImage, creator, members, fetchImage]);


    useEffect(()=>{
        const fetchJoinRequestsData = async ()=>{
            if(!joinRequests || joinRequests.length===0) return;

            if(!joinRequests.some((member)=>typeof member === "string")) return;

            const data = await Promise.all(joinRequests.map(async (member)=>{
                if(typeof member !== "string") return member;
                const username = await findUserNameDB(member);
                let avatar = await findAvatarDB(member);
                if(!avatar.includes("static")){
                    avatar = await fetchImage(avatar, false);
                }


                if(!username || !avatar){
                    console.log('possible undefined hit');
                    return null;
                } 
                //console.log(`username: ${username}, uid: ${member}, avatar: ${avatar}`);
                return {username, uid:member, avatar}; 
            }));
            setJoinRequests(data.filter(Boolean));
        
        }
        fetchJoinRequestsData();

    },[ joinRequests , fetchImage])

    const isJoined = ()=>{
        return members && members.includes(user.uid);
    }

    const isAdmin = ()=>{
        return admins && admins.includes(user.uid);
    }

    const deleteGroup = ()=>{
        try{
            setStatusPopup({
                title:"Delete Group",
                statusType:"warning",
                message:"Are you sure you want to delete this group?",
                onConfirm: async () => {
                    setStatusPopup({title:"", statusType:"", message:"", onConfirm: null, onCancel: null});
                    const response = await axiosInstance.delete(`/groups/${groupID}`); 
                    if (response.status===200){
                        console.log(response.data.message);
                        setStatusPopup({title:"Deleted", statusType:"success", message:response.data.message});
                        //alert(response.data.message);
                        props.onDelete();
                    }
                },
                onCancel: () =>{
                    setStatusPopup({title:"", statusType:"", message:"", onConfirm: null, onCancel: null});
                    return;
                }
            });
            
        }
        catch(err){
            console.log(err);
            console.log(err.response?.data?.message);
        }

    }

     const openPopup = ()=>{
        setIsPopupOpen(true);
    }

    const closePopup = ()=>{
        setIsPopupOpen(false);
    }

    const kickMember = async (kickedUID)=>{
        try{
            console.log(`Kicking ${kickedUID} by admin:${user.uid}`);
            const response = await axiosInstance.delete(`/groups/kick/${kickedUID}?groupId=${groupID}`); 
            if (response.status===200){
                console.log(response.data?.message);
                setStatusPopup({title:"Kicked", statusType:"success", message:response.data?.message});
                //alert(response.data?.message);
                setMembers(response.data?.group?.members);
            }
        }
        catch(err){
            console.log(err);
            console.log(err.response?.data?.message);
        }

    }

    const renameGroup = async (newName) =>{
        try{
            console.log(`New group name: ${newName}`);
            console.log("Group ID: ", groupID);
            const response = await axiosInstance.put(`/groups/${groupID}`, {name:newName, admin:user.uid}); 
            if (response.status===200){
                console.log(response.data.message);
                setStatusPopup({title:"Renamed", statusType:"success", message:response.data.message});
                //alert(response.data.message);
                setGroupName(newName);
            }
        }
        catch(err){
            console.log(err);
            setStatusPopup({title:"Error", statusType:"error", message:err.response?.data?.message});
            console.log(err.response?.data?.message);
        }
    }

    const joinGroup = async ()=>{
        try{
            const payload = {groupId:groupID};
            const response = await axiosInstance.post(`/groups/join/${user.uid}`, payload); 
            if (response.status===200){
                console.log(response.data.message);
                setStatusPopup({title:"Joined", statusType:"success", message:response.data.message});
                //alert(response.data.message);
            }
        }
        catch(err){
            if(err.response?.status===400){
                setStatusPopup({title:"Error", statusType:"error", message:err.response?.data?.message});
                //alert(err.response?.data?.message);
            }
            console.log(err);
            console.log(err.response?.data?.message);
        }
    }

    const leaveGroup = async ()=>{
        try{
            if (creator===user.uid){
                deleteGroup();
                return;
            }
            const response = await axiosInstance.delete(`/groups/leave/${user.uid}?groupId=${groupID}`); 
            if (response.status===200){
                console.log(response.data.message);
                setStatusPopup({title:"", statusType:"alert", message: "Left the group successfully."});
                //alert(response.data.message);
                setMembers(response.data?.group?.members);
            }
        }
        catch(err){
            console.log(err);
            console.log(err.response?.data?.message);
        }
    }

    const acceptMember = async(memberUID) =>{
        try{
            console.log(`Accepting ${memberUID} to group:${groupID}`);
            const payload = {groupId:groupID};
            const response = await axiosInstance.put(`/groups/accept/${memberUID}`, payload); 
            if (response.status===200){
                console.log(response.data.message);
                setStatusPopup({title:"Accepted", statusType:"success", message:response.data.message});
                //alert(response.data.message);
                setMembers(response.data?.group?.members);
                setJoinRequests(response.data?.group?.joinRequests);
            }
        }
        catch(err){
            console.log(err);
            console.log(err.response?.data?.message);
        }
    }

    const declineMember = async(memberUID) =>{
        try{
            console.log(`Rejecting ${memberUID}`);
            const payload = {groupId:groupID};
            const response = await axiosInstance.put(`/groups/decline/${memberUID}`, payload); 
            if (response.status===200){
                console.log(response.data.message);
                console.log(response.data.group);
                setStatusPopup({title:"Declined", statusType:"success", message:response.data.message});
                //alert(response.data.message);
                //setMembers(response.data.group?.members);
                setJoinRequests(response.data.group?.joinRequests);
            }
        }
        catch(err){
            console.log(err);
            console.log(err.response?.data?.message);
        }
    }

    const promoteMember = async(memberUID) =>{
        try{
            console.log(`Promoting ${memberUID} in group:${groupID}`);
            const payload = {groupId:groupID};
            const response = await axiosInstance.put(`/groups/promote/${memberUID}`, payload); 
            if (response.status===200){
                console.log(response.data.message);
                setStatusPopup({title:"Promoted", statusType:"success", message:response.data.message});
                //alert(response.data.message);
                setMembers(response.data?.group?.members);
                setAdmins(response.data?.group?.admins);
            }
        }
        catch(err){
            console.log(err);
            console.log(err.response?.data?.message);
        }
    }

    const updateUI = (newMembers)=>{
        setMembers(newMembers);
    }

    return (
        <div id="group-card">
          <div id="group-card-header">
            <div className="grouped">
                <img className="group-image" src={groupImage || defaultGroupImage} alt="groupImage"/>
                <ScreenTitle title={groupName}/>
            </div>
            {isJoined() && (<button className="leave-btn desktop-only" title="Leave Group" onClick={leaveGroup}><LeaveGroupIcon/></button>)}
          </div>
          <ul className="card-carousel">
            {membersAvatars && membersAvatars.map((avatar,index)=>{
                if (index<5){
                    return (  <li key={index} className="card-carousel-item">
                        <img className="group-member-avatar" src={avatar} alt="usersAvatar"/>
                    </li>);
                }
                else return null;
            }
            )}
          </ul>
          <div id="group-card-footer">
            { /*The logic here is basically: If not joined -> display Join. If joined, explore, if joined and admin, display manage/del*/
            !isJoined() 
            ? (<>
                <button className="join-btn desktop-only" title="Join Group"onClick={joinGroup}><JoinGroupIcon size="30"/></button>
                <button className="mobile-actions-btn" onClick={joinGroup}>Join Group</button>
               </>)
            :(<>
                <button title="Explore" className="explore-btn desktop-only" onClick={(e)=>goTo(`/groups/feed/${groupID}?cid=${chatID}`)}><ExplorePostsIcon size="28"/></button>
                <button title="Chat"className="chat-btn desktop-only" onClick={(e)=>goTo(`/chat/${chatID}`)}><GroupChatIcon size="30"/></button>
                {isAdmin() && (<div className="grouped desktop-only">
                    <button title="Manage" className="manage-btn" onClick={() => openPopup()}><ManageGroupIcon size="30"/></button>
                    <button title="Delete" className="delete-btn" onClick={deleteGroup}><DeleteIcon size="30"/></button>
                </div>)}
                <button className="mobile-actions-btn" onClick={() => setIsActionsPopupOpen(true)}>Manage Group</button>
            </> )}
          </div>
          <PopupModal isOpen={isPopupOpen} onClose={closePopup} styleId="invite-modal">
           <TabbedContent
                tabs={["Rename","Members", "Invite", "New Image"]}
                tabsContent={[
                    <ConfigureGroupWindow 
                        groupName={groupName} onRenameGroup={(newGroupName)=>renameGroup(newGroupName)} 
                        joinRequests={joinRequests} onAcceptInvite={acceptMember} onDeclineInvite={declineMember}/>,
                    <MembersListWindow self={user.uid} members={membersUsernames} membersAvatars={membersAvatars} 
                    admins={admins} removeMember={kickMember} onPromote={promoteMember}/>,
                    <InviteWindow onInviteFriend={(e, inviteMember)=>props.onInvite(e, inviteMember, groupID, updateUI)}/>,
                    <StatisticsNewImageWindow groupId={groupID} />
                ]}
                tabStyleId="manage-group-tabs"
           />

          </PopupModal>

          <PopupModal isOpen={isActionsPopupOpen} onClose={() => setIsActionsPopupOpen(false)} styleId="mobile-actions-modal">
            <div className="mobile-actions-list">
                <ScreenTitle title="Group Options"/>
                <button className="action-item" onClick={() => {goTo(`/groups/feed/${groupID}?cid=${chatID}`); setIsActionsPopupOpen(false);}}>Explore</button>
                <button className="action-item" onClick={() => {goTo(`/chat/${chatID}`); setIsActionsPopupOpen(false);}}>Chat</button>
                <button className="action-item" onClick={() => {leaveGroup(); setIsActionsPopupOpen(false);}}>Leave Group</button>
                {isAdmin() && (
                    <>
                        <button className="action-item" onClick={() => {openPopup(); setIsActionsPopupOpen(false);}}>Configure</button>
                        <button className="action-item delete-action" onClick={() => {deleteGroup(); setIsActionsPopupOpen(false);}}>Delete Group</button>
                    </>
                )}
            </div>
          </PopupModal>

          <PopupModal isOpen={!!statusPopup.statusType} onClose={ ()=> setStatusPopup({ title:"", statusType:"", message:""})}>
                <StatusWindowWrapper 
                    statusType={statusPopup.statusType} 
                    title={statusPopup.title}
                    message={statusPopup.message}
                    onConfirm={statusPopup.onConfirm}
                    onCancel={statusPopup.onCancel} 
                    onClose={() => setStatusPopup({ title:"", statusType:"", message:""})} 
                    />
          </PopupModal>
        </div>
    );
}